-- Dữ liệu ban đầu cho tab "Up website": các trang + việc cần làm + sản phẩm/dự án cần up
-- (lấy từ bảng "Lịch nội dung · Up website" nhóm đang dùng). Dòng nào đã có (cùng site + tên) thì bỏ qua.
  SELECT 'THC', 'Trang chủ', '/', 'Trang chính', 'thieu', 'Có slider, công trình, sản phẩm. Khối “Khách hàng & đối tác” chưa có logo. Giải thưởng nghệ nhân bị lặp 2 lần. Ghi “10+ năm kinh nghiệm” trong khi trang Về chúng tôi ghi 40 năm.', 1
  WHERE NOT EXISTS (SELECT 1 FROM web_pages WHERE site = 'THC' AND title = 'Trang chủ');
  SELECT 'THC', 'Về chúng tôi', '/ve-chung-toi', 'Doanh nghiệp', 'ok', 'Câu chuyện 40 năm khá đầy đủ (~10.000 ký tự), ~29 ảnh nhưng một số ảnh lặp.', 2
  WHERE NOT EXISTS (SELECT 1 FROM web_pages WHERE site = 'THC' AND title = 'Về chúng tôi');
  SELECT 'THC', 'Xưởng sản xuất', '/xuong-san-xuat', 'Doanh nghiệp', 'thieu', 'Có đoạn giới thiệu 5.000m² – 3 tầng, 11 ảnh. Chưa có ảnh/video từng công đoạn.', 3
