  SELECT 'THC', 'Ngói âm dương', '/san-pham/ngoi-am-duong', 'Sản phẩm', 'thieu', '12 mẫu, tên thật. Giá ở danh sách 945.000 đ/m² nhưng trang chi tiết (vd mẫu /34) ghi 500.000 đ/m². Mẫu “sen cành đỏ cờ” lại có mô tả men xanh đồng, hoa mai. Khối Mái bê tông / Mái gỗ có 3 bước giống nhau (chữ mẫu). Mẫu nào cũng gắn công trình Thư viện Lê Đức Anh.', 6
  WHERE NOT EXISTS (SELECT 1 FROM web_pages WHERE site = 'THC' AND title = 'Ngói âm dương');
  SELECT 'THC', 'Ngói hài văn miếu', '/san-pham/ngoi-hai-van-mieu', 'Sản phẩm', 'mau', '12 mẫu đặt tên kiểu “Phục chế cổ – Bản số 4…15”, giá tăng đều 500đ mỗi mẫu → dữ liệu mẫu.', 7
  WHERE NOT EXISTS (SELECT 1 FROM web_pages WHERE site = 'THC' AND title = 'Ngói hài văn miếu');
  SELECT 'THC', 'Gạch hoa thông gió', '/san-pham/gach-hoa-thong-gio', 'Sản phẩm', 'thieu', '12 mẫu có tên riêng (Vân xoắn, Bát quái, Cửu long…); cần xác nhận đúng mẫu đang sản xuất.', 8
  WHERE NOT EXISTS (SELECT 1 FROM web_pages WHERE site = 'THC' AND title = 'Gạch hoa thông gió');
  SELECT 'THC', 'Phụ kiện ngói', '/san-pham/phu-kien-ngoi', 'Sản phẩm', 'mau', '~25 sản phẩm (ngói bò nóc 15 màu, bộ nóc chữ vạn 10 màu) nhưng không bấm vào xem chi tiết được; giá tăng đều 1.000đ → dữ liệu mẫu.', 9
  WHERE NOT EXISTS (SELECT 1 FROM web_pages WHERE site = 'THC' AND title = 'Phụ kiện ngói');
