  SELECT 'THC', 'Đèn gốm sứ', '/san-pham/den-gom-su', 'Sản phẩm', 'mau', '15 sản phẩm = 5 kiểu lặp “Mẫu 1…15”, giá “Từ …”. Menu gọi “Đèn gốm sứ”, footer gọi “Đèn vườn gốm sứ”.', 14
